#include "GPIO.h"
#include "Rte_DoorLockIndication_SWC.h"
#include "Rte_DoorSensorAbstraction_SWC.h"

void HW_Init(){

	RCC_GPIOA_CLK_EN();

	GPIO_Configure_Pin_t Door ;
	Door.GPIO_Mode = GPIO_Floating_Input ;
	Door.GPOI_Pin_Number = GPIO_PIN3 ;
	MCAL_GPIO_Init(GPIOA,&Door);



	Door.GPIO_Mode = output_push_pull   ;
	Door.GPIO_Output_Frequency = Frequency_10MHz  ;
	Door.GPOI_Pin_Number = GPIO_PIN7 ;
	MCAL_GPIO_Init(GPIOA,&Door);
}
void OS_Start(){

	unsigned char i = 0 ;
	while(1){
		if (i == 10) {

		ReadDoorSensor_Run();
			i++ ;

		} else if (i == 12) {
		DoorLockIndication_Run();
			i++ ;
		}else{
			i++;
		}
	}



}
int main(void)
{
	HW_Init();
	OS_Start();
	for(;;);
}
